def run_git(root, *args):
    return subprocess.check_output(["git", "-C", str(root), *args], text=True).strip()


def normalized_sources(feature_row):
    result = []
    for item in feature_row["upstreamSources"]:
        if item.startswith("viewer/"):
            result.append(item)
        else:
            result.append("src/" + item + ".rs")
    return result


def evidence(path, root):
    raw = pinned_bytes(path, root)
    text = raw.decode(errors="replace")
    docs = []
    for line in text.splitlines()[:45]:
        if line.startswith("//!"):
            docs.append(line[3:].strip())
    exports = re.findall(r"^pub(?:\([^)]*\))?\s+(?:fn|struct|enum|type)\s+(\w+)", text, re.M)
    first = next((index + 1 for index, line in enumerate(text.splitlines()) if re.match(r"pub(?:\([^)]*\))?\s+", line)), 1)
    return dict(path=str(path.relative_to(root)), sha256=hashlib.sha256(raw).hexdigest(),
                declarationExcerpt=" ".join(docs)[:1100], publicSymbols=exports,
                sourceUrl=f"https://github.com/helenkwok/rvt-rs/blob/{PIN}/{path.relative_to(root)}#L{first}")


def pinned_bytes(path, root):
    name = str(path.relative_to(root))
    key = (str(root), name)
    if key not in PIN_CONTENTS:
        PIN_CONTENTS[key] = subprocess.check_output(["git", "-C", str(root), "show", f"{PIN}:{name}"])
    return PIN_CONTENTS[key]


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--upstream-root", default=str(ROOT.parent / "rvt-rs-upstream"))
    parser.add_argument("--output", default=str(ROOT / "docs/rvt-upstream-capability-inventory.json"))
    args = parser.parse_args()
    upstream = Path(args.upstream_root).resolve()
    commit = run_git(upstream, "rev-parse", "HEAD")
    if commit != PIN:
        raise SystemExit(f"Expected upstream {PIN}, found {commit}")
    pinned_files = set(run_git(upstream, "ls-tree", "-r", "--name-only", PIN).splitlines())
    modules = [upstream / name for name in sorted(pinned_files) if name.startswith("src/") and name.endswith(".rs")]
    assigned = {}
    rows = []
    for definition in FEATURES:
        row = dict(definition)
        row["upstreamSources"] = normalized_sources(row)
        for name in row["upstreamSources"]:
            if name not in pinned_files:
                raise SystemExit(f"Unknown source reference: {name}")
            assigned.setdefault(name, []).append(row["id"])
        row["upstreamEvidence"] = [evidence(upstream / name, upstream) for name in row["upstreamSources"]]
        row["localEvidencePresent"] = [name for name in row["reviterSources"] if (ROOT / name).is_file()]
        row["localEvidenceMissing"] = [name for name in row["reviterSources"] if not (ROOT / name).is_file()]
        row["localEvidence"] = [dict(path=name, sha256=hashlib.sha256((ROOT / name).read_bytes()).hexdigest(),
                                     exportedSymbols=re.findall(r"^export\s+(?:async\s+)?(?:function|class|const|type|interface)\s+(\w+)", (ROOT / name).read_text(), re.M))
                                for name in row["localEvidencePresent"]]
        row["regressionSuitesPresent"] = [name for name in row["regressionSuites"] if (ROOT / name).is_file()]
        row["regressionSuitesMissing"] = [name for name in row["regressionSuites"] if not (ROOT / name).is_file()]
        row["verificationState"] = "referenced sources/suites exist; execution results are tracked separately" if not row["localEvidenceMissing"] and not row["regressionSuitesMissing"] else "partially pending; missing paths are explicit"
        rows.append(row)
    # Every shipped CLI gets an explicit cross-project interpretation, not a
    # guessed claim that similarly named shell scripts are drop-in replacements.
    cli_map = {
        "gen_fixture": ("research", "nonapplicable", "Synthetic Rust test fixture generator; Reviter has independent synthetic fixtures."),
        "rvt_analyze": ("metadata", "narrower", "Metadata/coverage audit exists, but a unified forensic/disclosure report is not replicated."),
        "rvt_capabilities": ("controls", "new-port", "capabilities:rvt gives exact admission/evidence contracts; research ES domains are deliberately separate."),
        "rvt_corpus": ("research", "nonapplicable", "Byte-level multi-release delta inference remains an upstream research tool."),
        "rvt_diff": ("research", "nonapplicable", "Upstream compares decompressed streams; Reviter differential-convert compares conversion outcomes."),
        "rvt_doc": ("native-records", "narrower", "Bounded selected native graphs and typed inventory are exposed; complete ADocument recovery is not claimed."),
        "rvt_dump": ("container", "narrower", "Reviter extraction/audit tools consume streams; no equivalent all-stream forensic dump CLI is claimed."),
        "rvt_elem_table": ("identity", "existing", "Complete schema-validated ElemTable/source ownership inventory supplements legacy scene admission and native identities."),
        "rvt_elements": ("native-records", "narrower", "Element manifest exists; generic field-by-field decoded-object/typed JSON contract is absent."),
        "rvt_gltf": ("scene-export", "existing", "Reviter exports native/recovered scene GLB through its own geometry pipeline."),
        "rvt_history": ("native-records", "gap", "Upgrade-history UTF16 string scan is distinct from native creation-episode identity history."),
        "rvt_ifc": ("ifc-quality", "narrower", "Reviter exports typed native/recovered IFC with different geometry/provenance and no identical strict quality policy."),
        "rvt_ifc_compare": ("comparison", "new-port", "New source-hash/binary-pinned reader comparison supplements existing paired IFC QA."),
        "rvt_info": ("metadata", "new-port", "Standalone safe metadata inventory added; upstream folder discovery/report CLI remains separate."),
        "rvt_inspect": ("ifc-quality", "narrower", "Reader/decoder readiness diagnostics exist; upstream health policy is not an equivalent quality certificate."),
        "rvt_schedule": ("scene-export", "new-port", "CSV inventories and selected stored ScheduleSchema fields exist; recalculated authored schedules remain unsupported."),
        "rvt_schema": ("schema", "existing", "Reviter schema reader and schema audit scripts provide file-local schema information."),
        "rvt_sheet": ("scene-export", "existing", "Reviter SVG plan/floor rendering already exists, using independent geometry evidence."),
        "rvt_write": ("writing", "nonapplicable", "Native RVT writing/patching is outside the source-preserving converter integration."),
    }
    cli_rows = []
    for path in [upstream / name for name in sorted(pinned_files) if name.startswith("src/bin/") and name.endswith(".rs")]:
        group, status, scope = cli_map[path.stem]
        name = str(path.relative_to(upstream))
        assigned.setdefault(name, []).append(group)
        cli_rows.append(dict(**evidence(path, upstream), feature=group, disposition=status, interpretation=scope))
    uncovered = [str(path.relative_to(upstream)) for path in modules if str(path.relative_to(upstream)) not in assigned]
    if uncovered:
        raise SystemExit("Unclassified upstream source modules: " + ", ".join(uncovered))
    # Binding and viewer surfaces are enumerated completely. Build/runtime/test
    # assets are recorded as infrastructure, not inferred model capabilities.
    surfaces = []
    for directory in ["rvt-wasm", "rvt-py", "python", "viewer"]:
        for path in [upstream / name for name in sorted(pinned_files) if name.startswith(directory + "/")]:
            if any(part in {"pkg", "node_modules", "dist", "__pycache__", ".git"} for part in path.parts):
                continue
            name = str(path.relative_to(upstream))
            status = "existing" if name == "rvt-wasm/src/lib.rs" else "nonapplicable" if directory in {"rvt-py", "python"} else "existing" if name in {"viewer/src/main.ts", "viewer/src/worker.ts"} else "nonapplicable"
            surfaces.append(dict(path=name, sha256=hashlib.sha256(pinned_bytes(path, upstream)).hexdigest(), disposition=status,
                                 interpretation="Pinned JS/WASM public IFC/metadata API is integrated. A separately declared Reviter-only binding patch exposes bounded native graph/ES evidence; this pinned vanilla API remains unchanged." if name == "rvt-wasm/src/lib.rs" else "Python packaging/bindings are a distinct host surface; decoder capabilities are accounted for by core source module rows." if directory in {"rvt-py", "python"} else "Local-file viewer behavior overlaps Reviter; source modules are assessed separately from bundler/styles/tests/demo assets."))
    probes = [dict(path=name, disposition="nonapplicable", sha256=hashlib.sha256(pinned_bytes(upstream / name, upstream)).hexdigest()) for name in sorted(pinned_files) if name.startswith("examples/") and name.endswith(".rs")]
    fuzz = [dict(path=name, disposition="narrower", interpretation="Native Rust/libFuzzer parser target; Reviter's bounded TypeScript corpus does not cover this target automatically.") for name in sorted(pinned_files) if name.startswith("fuzz/fuzz_targets/") and name.endswith(".rs")]
    manifest = dict(schemaVersion=1, generatedBy="scripts/inventory-rvt-upstream-capabilities.py",
                    thirdPartyAttribution=dict(license="Apache-2.0", notice="docs/third-party/rvt-rs/NOTICE", licenseFile="docs/third-party/rvt-rs/LICENSE", provenance="docs/rvt-semantic-attribution.md"),
                    upstream=dict(repository="https://github.com/helenkwok/rvt-rs", commit=commit, sourceModules=len(modules), dirty=bool(run_git(upstream, "status", "--porcelain"))),
                    reviter=dict(repository="https://github.com/ahzs645/reviter", baseCommit=run_git(ROOT, "rev-parse", "HEAD"), workingTreeChanges=run_git(ROOT, "status", "--porcelain").splitlines()),
                    scope="Every pinned src/**/*.rs module, every CLI, all viewer/Python/WASM package files, Rust examples and fuzz entry points are enumerated. Capability equivalence is assessed by behavior and evidence, not matching names.",
                    statusDefinitions=dict(existing="Behavior overlaps existing Reviter functionality; not byte/layout/coverage parity.", **{"new-port": "A concrete new integration is being implemented; local source/test availability and final execution evidence are reported separately."}, narrower="Overlap exists, but upstream exposes additional semantic fields/surfaces or different release/quality gates.", gap="Concrete upstream capability lacks a faithful Reviter equivalent within current source evidence.", unresolved="Both have independent implementations; owner/corpus comparisons are required before claiming equivalence or a useful port.", nonapplicable="Writer/host packaging/research/build infrastructure does not belong in this read-only browser converter integration."),
                    features=rows, sourceModules=[dict(**evidence(path, upstream), featureIds=assigned[str(path.relative_to(upstream))]) for path in modules],
                    commandLineTools=cli_rows, bindingAndViewerFiles=surfaces, researchExamples=probes, nativeFuzzTargets=fuzz,
                    uncoveredSourceModules=uncovered,
                    limitations=["Declaration excerpts and public symbols are source witnesses, not proof of positive real-model decoder coverage.", "Missing local evidence is explicitly pending; a suite path in this inventory is not a claim it ran or passed.", "Counts of modules/features are inventory completeness measures, not supported-element, geometry or semantic completeness percentages.", "General native object graphs, parameter-definition namespaces, Extensible Storage, source drafting metadata and IFC authoring profiles remain distinct from the selectively ported semantics."])
    output = Path(args.output)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"Inventoried {len(modules)} source modules, {len(cli_rows)} CLIs, {len(surfaces)} binding/viewer assets, {len(probes)} research examples; uncovered={len(uncovered)}")
    print(output)


if __name__ == "__main__":
    main()
